//! Stage 4 acceptance tests against real Audacity 3.7.3 `.aup3` files
//! (generated by `rust/tools/make_aup3_fixtures.sh`).

use au_project::aup3::{self, DocSource};
use au_project::blocks::{self, SampleFormat};
use au_core::timeline::Clip;
use au_core::AudioBuffer;
use rusqlite::Connection;
use std::path::{Path, PathBuf};

fn fx(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/aup3").join(name)
}

fn copy_fx(name: &str, dir: &tempfile::TempDir) -> PathBuf {
    let p = dir.path().join(name);
    std::fs::copy(fx(name), &p).unwrap();
    p
}

const ALL: [&str; 4] = [
    "int16_mono_clips_labels.aup3",
    "float_stereo_48k.aup3",
    "int24_mono_long.aup3",
    "crash_unsaved_edit.aup3",
];

#[test]
fn reads_int16_clips_envelope_labels_selection() {
    let p = aup3::load(&fx("int16_mono_clips_labels.aup3")).unwrap();
    let s = &p.state;
    assert_eq!(s.sample_rate, 44100);
    assert_eq!(s.tracks.len(), 1);
    let t = &s.tracks[0];
    assert_eq!(t.name, "Sine");
    assert!(t.solo && !t.mute);
    assert!((t.pan - 0.25).abs() < 1e-6);
    assert_eq!(t.clips.clips.len(), 2);
    let (a, b) = (&t.clips.clips[0], &t.clips.clips[1]);
    assert_eq!((a.start, a.buffer.len(), a.name.as_str()), (0, 44100, "Audio 1.1"));
    assert_eq!((b.start, b.buffer.len(), b.name.as_str()), (88200, 22050, "Audio 1.2"));
    // Raw int16 values read independently with Python's struct module.
    let raw = [(0usize, 0.0f32), (1, 0.031341552734375), (37, 0.366241455078125), (100, -0.010528564453125)];
    for (i, v) in raw {
        assert_eq!(a.buffer.channels[0][i], v, "sample {i}");
    }
    let peak = a.buffer.channels[0].iter().fold(0f32, |m, x| m.max(x.abs()));
    assert!((peak - 0.5).abs() < 0.002);
    let env = &t.clips.envelope.points;
    assert_eq!(env.len(), 2);
    assert!((env[0].time - 0.5).abs() < 1e-9 && (env[0].value - 0.5).abs() < 1e-9);
    assert!((env[1].time - 0.9).abs() < 1e-9);
    assert_eq!(s.labels.len(), 1);
    let l = &s.labels[0].labels;
    assert_eq!(l.len(), 2);
    assert_eq!((l[0].start, l[0].end, l[0].text.as_str()), (0.0, 0.5, "intro"));
    assert_eq!((l[1].start, l[1].text.as_str()), (2.2, "point"));
    assert_eq!(p.extras.selection, (0.25, 0.75));
    assert_eq!(p.extras.track_formats, vec![SampleFormat::Int16]);
    assert_eq!(p.extras.user_version, 0x0307_0000);
    assert_eq!(p.extras.audacity_version, "3.7.3");
}

#[test]
fn reads_float_stereo_and_int24_multiblock() {
    let p = aup3::load(&fx("float_stereo_48k.aup3")).unwrap();
    let t = &p.state.tracks[0];
    assert_eq!((p.state.sample_rate, p.state.tracks.len()), (48000, 1));
    assert_eq!(t.clips.clips[0].buffer.n_channels(), 2);
    assert_eq!(t.clips.clips[0].buffer.len(), 96000);
    assert!(t.mute && (t.pan + 0.5).abs() < 1e-6);
    assert_ne!(t.clips.clips[0].buffer.channels[0], t.clips.clips[0].buffer.channels[1]);
    let q = aup3::load(&fx("int24_mono_long.aup3")).unwrap();
    assert_eq!(q.extras.track_formats, vec![SampleFormat::Int24]);
    assert_eq!(q.state.tracks[0].clips.clips[0].buffer.len(), 308700);
    assert_eq!(q.state.tracks[0].name, "Chirp");
}

/// Our summaries must equal the ones Audacity stored, byte for byte.
#[test]
fn summaries_match_audacity_bytes() {
    for f in ALL {
        let c = Connection::open(fx(f)).unwrap();
        let mut st = c
            .prepare("SELECT sampleformat, summin, summax, sumrms, summary256, summary64k, samples FROM sampleblocks")
            .unwrap();
        let rows = st
            .query_map([], |r| {
                Ok((r.get::<_, i64>(0)?, r.get::<_, f64>(1)?, r.get::<_, f64>(2)?, r.get::<_, f64>(3)?,
                    r.get::<_, Vec<u8>>(4)?, r.get::<_, Vec<u8>>(5)?, r.get::<_, Vec<u8>>(6)?))
            })
            .unwrap();
        for row in rows {
            let (fmt, mn, mx, rms, s256, s64k, samples) = row.unwrap();
            let fmt = SampleFormat::from_code(fmt as u32).unwrap();
            let dec = blocks::decode_samples(&samples, fmt);
            assert_eq!(blocks::encode_samples(&dec, fmt), samples, "{f}: sample re-encode");
            let s = blocks::summarize(&dec);
            assert_eq!(s.summary256, s256, "{f}: summary256");
            assert_eq!(s.summary64k, s64k, "{f}: summary64k");
            assert_eq!((s.min as f64, s.max as f64), (mn, mx), "{f}: min/max");
            assert!((s.rms - rms).abs() < 1e-9, "{f}: rms {} vs {}", s.rms, rms);
        }
    }
}

#[test]
fn open_save_reopen_round_trip_is_lossless() {
    let dir = tempfile::tempdir().unwrap();
    for f in ALL {
        let orig = aup3::load(&fx(f)).unwrap();
        let out = dir.path().join(format!("rt_{f}"));
        aup3::save(&out, &orig).unwrap();
        assert_eq!(aup3::integrity_check(&out).unwrap(), "ok");
        let back = aup3::load(&out).unwrap();
        assert_eq!(back.state, orig.state, "{f}");
        assert_eq!(back.extras.selection, orig.extras.selection);
        assert_eq!(back.extras.track_formats, orig.extras.track_formats);
        // Stored sample bytes identical to Audacity's.
        let blobs = |p: &Path| -> Vec<Vec<u8>> {
            let c = Connection::open(p).unwrap();
            let mut s = c.prepare("SELECT samples FROM sampleblocks ORDER BY blockid").unwrap();
            let v = s.query_map([], |r| r.get(0)).unwrap().map(|x| x.unwrap()).collect();
            v
        };
        let mut want = blobs(&fx(f));
        if f.starts_with("crash") {
            want.truncate(1); // block 2 is an orphan of the unsaved edit
        }
        assert_eq!(blobs(&out), want, "{f}: sample blobs");
        let c = Connection::open(&out).unwrap();
        let app: i32 = c.query_row("PRAGMA application_id", [], |r| r.get(0)).unwrap();
        assert_eq!(app, aup3::APPLICATION_ID);
        let ver: i64 = c.query_row("PRAGMA user_version", [], |r| r.get(0)).unwrap();
        assert_eq!(ver as u32, 0x0307_0000, "version of the source file is kept");
    }
}

#[test]
fn schema_matches_audacity() {
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("s.aup3");
    aup3::save(&out, &aup3::load(&fx("int16_mono_clips_labels.aup3")).unwrap()).unwrap();
    let sql = |p: &Path| -> Vec<String> {
        let c = Connection::open(p).unwrap();
        let mut s = c.prepare("SELECT sql FROM sqlite_master ORDER BY name").unwrap();
        let v = s.query_map([], |r| r.get(0)).unwrap().map(|x| x.unwrap()).collect();
        v
    };
    assert_eq!(sql(&out), sql(&fx("int16_mono_clips_labels.aup3")));
}

#[test]
fn golden_xml_differences_are_documented() {
    // Intentional differences vs Audacity's own document are listed in
    // docs/AUP3_FORMAT.md; check the stable core survives our writer.
    let dir = tempfile::tempdir().unwrap();
    let out = dir.path().join("g.aup3");
    aup3::save(&out, &aup3::load(&fx("int16_mono_clips_labels.aup3")).unwrap()).unwrap();
    let ours = aup3::dump_xml(&out, DocSource::Saved).unwrap();
    for needle in ["<project", "<wavetrack", "<waveclip", "<sequence", "<waveblock", "<envelope",
                   "<controlpoint", "<labeltrack", "<label", "title=\"intro\"", "sampleformat=\"131073\""] {
        assert!(ours.contains(needle), "missing {needle}:\n{ours}");
    }
}

#[test]
fn crash_recovery_from_autosave() {
    let dir = tempfile::tempdir().unwrap();
    let path = copy_fx("crash_unsaved_edit.aup3", &dir);
    let info = aup3::inspect(&path).unwrap();
    assert!(info.has_saved && !info.needs_recovery);
    // The real killed Audacity session left its unsaved edit's block orphaned.
    assert_eq!(info.orphan_blocks, 1);
    // Simulate an edit session that dies before saving.
    let mut p = aup3::load(&path).unwrap();
    assert_eq!(p.state.tracks[0].name, "Saved");
    p.state.tracks[0].name = "Unsaved".into();
    p.state.tracks[0].clips.clips.push(Clip::new("Audio 1.2", 44100, AudioBuffer::from_channels(44100, vec![vec![0.25; 22050]])));
    aup3::autosave(&path, &p).unwrap();
    assert_eq!(aup3::integrity_check(&path).unwrap(), "ok");
    assert!(aup3::inspect(&path).unwrap().needs_recovery);
    // Saved doc is untouched; autosave holds the edit.
    assert_eq!(aup3::load(&path).unwrap().state.tracks[0].name, "Saved");
    let rec = aup3::load_from(&path, DocSource::Autosave).unwrap();
    assert_eq!(rec.state, p.state);
    // Discard path.
    let path2 = dir.path().join("discard.aup3");
    std::fs::copy(&path, &path2).unwrap();
    aup3::discard_autosave(&path2).unwrap();
    assert!(!aup3::inspect(&path2).unwrap().needs_recovery);
    assert_eq!(aup3::load(&path2).unwrap().state.tracks[0].clips.clips.len(), 1);
    // Recover path: becomes the saved doc, autosave cleared.
    let r = aup3::recover(&path).unwrap();
    assert_eq!(r.state, p.state);
    let info = aup3::inspect(&path).unwrap();
    assert!(!info.needs_recovery);
    assert_eq!(info.orphan_blocks, 0);
    assert_eq!(aup3::load(&path).unwrap().state, p.state);
}

#[test]
fn temporary_project_autosave_only() {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("untitled.aup3");
    let p = aup3::load(&fx("float_stereo_48k.aup3")).unwrap();
    aup3::autosave(&path, &p).unwrap();
    assert!(aup3::inspect(&path).unwrap().needs_recovery);
    assert_eq!(aup3::load(&path).unwrap().state, p.state);
}

#[test]
fn stretch_ratio_bumps_version_and_round_trips() {
    let dir = tempfile::tempdir().unwrap();
    let mut p = aup3::load(&fx("int16_mono_clips_labels.aup3")).unwrap();
    p.extras.user_version = aup3::VERSION_3_0;
    p.state.tracks[0].clips.clips[1].stretch_ratio = 1.5;
    p.state.tracks[0].gain = 0.5;
    let out = dir.path().join("st.aup3");
    aup3::save(&out, &p).unwrap();
    assert_eq!(aup3::inspect(&out).unwrap().user_version, aup3::VERSION_3_4);
    let back = aup3::load(&out).unwrap();
    assert_eq!(back.state.tracks[0].clips.clips[1].stretch_ratio, 1.5);
    assert_eq!(back.state.tracks[0].gain, 0.5);
}

#[test]
fn rejects_non_audacity_and_newer_files() {
    let dir = tempfile::tempdir().unwrap();
    let p = dir.path().join("x.aup3");
    Connection::open(&p).unwrap().execute_batch("CREATE TABLE t(x);").unwrap();
    assert!(aup3::load(&p).is_err());
    let q = copy_fx("int16_mono_clips_labels.aup3", &dir);
    Connection::open(&q).unwrap().execute_batch("PRAGMA user_version = 67633152;").unwrap(); // 4.8.0.0
    assert!(aup3::load(&q).unwrap_err().to_string().contains("newer"));
}
